import java.util.*;
import java.io.*;

public class Main {
    static final int INF = 2000000000;
    static final int MAXN = 210;
    static final int MAXM = 2 * MAXN * MAXN;
    static final int[] dx = {1, 0, 0, -1};
    static final int[] dy = {0, 1, -1, 0};
    static final int S = MAXN - 2;
    static final int T = MAXN - 1;

    static class MaxFlow {
        int[] to = new int[MAXM];
        int[] flow = new int[MAXM];
        int[] cap = new int[MAXM];
        int lastEdge;
        List<Integer>[] g = new ArrayList[MAXN];
        boolean[] used = new boolean[MAXN];

        public MaxFlow() {
            for (int i = 0; i < MAXN; i++) {
                g[i] = new ArrayList<>();
            }
            lastEdge = 0;
        }

        void addEdge(int from, int to, int cap) {
            this.to[lastEdge] = to;
            this.flow[lastEdge] = 0;
            this.cap[lastEdge] = cap;
            g[from].add(lastEdge++);
            this.to[lastEdge] = from;
            this.flow[lastEdge] = 0;
            this.cap[lastEdge] = 0;
            g[to].add(lastEdge++);
        }

        boolean dfs(int v, int T, int curFlow) {
            if (v == T) return true;
            used[v] = true;
            for (int idx : g[v]) {
                if (!used[to[idx]] && cap[idx] - flow[idx] >= curFlow && dfs(to[idx], T, curFlow)) {
                    flow[idx] += curFlow;
                    flow[idx ^ 1] -= curFlow;
                    return true;
                }
            }
            return false;
        }

        int maxFlow(int S, int T) {
            int totalFlow = 0;
            int curFlow = 1 << 30;
            while (curFlow > 0) {
                Arrays.fill(used, false);
                if (dfs(S, T, curFlow))
                    totalFlow += curFlow;
                else
                    curFlow >>= 1;
            }
            return totalFlow;
        }
    }

    static int n, t;
    static char[][] a = new char[15][15];
    static char[][] b = new char[15][15];
    static int[][] dist = new int[15][15];
    static boolean[][] used = new boolean[15][15];
    static MaxFlow mf = new MaxFlow();

    static boolean ok(int x, int y) {
        return 0 <= x && x < n && 0 <= y && y < n && a[x][y] != 'Y' && a[x][y] != 'Z';
    }

    static void bfsDeath(int x, int y) {
        for (int i = 0; i < n; i++)
            Arrays.fill(dist[i], Integer.MAX_VALUE);
        Queue<Integer> X = new LinkedList<>();
        Queue<Integer> Y = new LinkedList<>();
        dist[x][y] = 0;
        X.offer(x);
        Y.offer(y);
        while (!X.isEmpty()) {
            int cx = X.poll();
            int cy = Y.poll();
            for (int k = 0; k < 4; k++) {
                int tx = cx + dx[k];
                int ty = cy + dy[k];
                if (ok(tx, ty) && dist[tx][ty] == Integer.MAX_VALUE) {
                    dist[tx][ty] = dist[cx][cy] + 1;
                    X.offer(tx);
                    Y.offer(ty);
                }
            }
        }
    }

    static void runBFS(int x, int y) {
        Queue<Integer> X = new LinkedList<>();
        Queue<Integer> Y = new LinkedList<>();
        Queue<Integer> lev = new LinkedList<>();
        for (int i = 0; i < n; i++)
            Arrays.fill(used[i], false);
        used[x][y] = true;
        X.offer(x);
        Y.offer(y);
        lev.offer(0);
        while (!X.isEmpty()) {
            int cx = X.poll();
            int cy = Y.poll();
            int levl = lev.poll();
            if (Character.isDigit(b[cx][cy]) && b[cx][cy] != '0') {
                mf.addEdge(x * n + y, n * n + 1 + cx * n + cy, INF);
            }
            if (levl >= t) continue;
            for (int k = 0; k < 4; k++) {
                int tx = cx + dx[k];
                int ty = cy + dy[k];
                if (ok(tx, ty) && !used[tx][ty]) {
                    if (dist[tx][ty] > levl + 1) {
                        X.offer(tx);
                        Y.offer(ty);
                        lev.offer(levl + 1);
                    } else if (dist[tx][ty] > levl && Character.isDigit(b[tx][ty]) && b[tx][ty] != '0') {
                        mf.addEdge(x * n + y, n * n + 1 + tx * n + ty, INF);
                    }
                    used[tx][ty] = true;
                }
            }
        }
    }

    static void build() {
        int px = -1, py = -1;
        for (int i = 0; i < n && px == -1; i++) {
            for (int j = 0; j < n && px == -1; j++) {
                if (a[i][j] == 'Z') {
                    px = i;
                    py = j;
                }
            }
        }
        bfsDeath(px, py);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (Character.isDigit(a[i][j]) && a[i][j] != '0') {
                    mf.addEdge(S, i * n + j, a[i][j] - '0');
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (Character.isDigit(b[i][j]) && b[i][j] != '0') {
                    mf.addEdge(i * n + j + n * n + 1, T, b[i][j] - '0');
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (Character.isDigit(a[i][j]) && a[i][j] != '0') {
                    runBFS(i, j);
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());
        for (int i = 0; i < n; i++) {
            a[i] = br.readLine().toCharArray();
        }
        for (int i = 0; i < n; i++) {
            b[i] = br.readLine().toCharArray();
        }
        build();
        System.out.println(mf.maxFlow(S, T));
    }
}
